node.script:
function UsersEnter(so_self)
{
	for (local i = 0; i < 4; i++)
	{
		local so_user = StageObject_GetKeyValue(so_self, "user_" + i);
		if (so_user != null)
			StageObject_SetParentButRetainStageTransform(so_user, so_self);
	}
}

function UsersLeave(so_self)
{
	for (local i = 0; i < 4; i++)
	{
		local so_user = StageObject_GetKeyValue(so_self, "user_" + i);
		if (so_user != null)
		{
			StageObject_SetParentButRetainStageTransform(so_user, 0);
			StageObject_SetGlobal(so_user, true);
		}
	}
}

function OnStart(so_self, length)
{
	StageObject_SetKeyValueFloat(so_self, "base_z", StageObject_GetPosition(so_self)[2]);
	UsersEnter(so_self);
	Actor_SetActorFlag(so_self, "STATIC", false);
}

function OnUpdate(so_self, time_key, length)
{
	local pos = StageObject_GetPosition(so_self);
	if (pos == null)
		return;

	local base_z = StageObject_GetKeyValue(so_self, "base_z");
	StageObject_SetPosition(so_self, pos[0], pos[1], base_z + 50 * time_key);
}

function OnEnd(so_self, length)
{
	UsersLeave(so_self);
	Actor_SetActorFlag(so_self, "STATIC", true);
}

