node.interaction_1_script_to_run_on_interacti:
function AreSamePlayers(so_1, so_2)
{
	local i1 = Game_GetPlayerIndexByActor(so_1);
	local i2 = Game_GetPlayerIndexByActor(so_2);
	if (i1 == null || i2 == null)
		return;
	if (i1 < 0 || i2 < 0)
		return;
	return i1 == i2;
}

function OnInteraction(so_self, so_activator)
{
	Game_SetStagePointOfInterestCompleted(so_self);

	if (AreSamePlayers(Game_GetAnyPlayerActor(), so_activator))
	{
		for (local i = 0; i < 4; i++)
		{
			local user = "user_" + i;
			local player_actor = Game_GetPlayerActor(i);
			if (player_actor != null)
			{
				StageObject_SetKeyValueStageObjectReference(so_self, user, player_actor);
				StageObject_SetParentButRetainStageTransform(player_actor, so_self);
				StageObject_SetPosition(player_actor, 10-i*35, -i*25, 0);
				StageObject_SetAngle(player_actor, 0);

				local so_pet = StageObject_GetKeyValueStageObjectReference(player_actor,"ref_pet");
				if (so_pet != null)
				{
					StageObject_SetParentButRetainStageTransform(so_pet, so_self);
					StageObject_SetPosition(so_pet, 15-i*35, -i*25+5, 0);
					StageObject_SetAngle(so_pet, 0);
				}
			}
		}
	}

	Game_SetCinemaMode(true, true);
	local script_start = @"
		local anim_id = StageObject_GetKeyValue($so_self, ""enter_animation"");
		if (!Actor_IsAnimationPlaying($so_self, anim_id))
			Actor_PlayAnimation($so_self, anim_id);

		Game_SetCinemaMode(true);
		Actor_SetActorFlag($so_activator, ""SOLID"", false);
	";

	script_start = string_replace(script_start, "$so_activator", so_activator);
	script_start = string_replace(script_start, "$so_self", so_self);

	Actor_QueueActionRunScript(so_activator, script_start);

	local script_end = @"
		Game_SetCinemaMode(false);
		Actor_SetActorFlag($so_activator, ""SOLID"", true);
	";

	script_end = string_replace(script_end, "$so_activator", so_activator);
	script_end = string_replace(script_end, "$so_self", so_self);

	Actor_QueueActionRunScript(so_activator, script_end);
}
